import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Understanding Hearth","description":"Hearth's product positioning, target users, core capabilities, and current status.","frontmatter":{"title":"Understanding Hearth","description":"Hearth's product positioning, target users, core capabilities, and current status.","outline":[2,3]},"headers":[],"relativePath":"en/guide/what-is-hearth.md","filePath":"en/guide/what-is-hearth.md","lastUpdated":1793752688000}`),o={name:"en/guide/what-is-hearth.md"};function r(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<p class="eyebrow">PROJECT INTRODUCTION</p><h1 id="hearth-turning-digital-labor-into-reliable-tasks" tabindex="-1">Hearth: Turning Digital Labor into Reliable Tasks <a class="header-anchor" href="#hearth-turning-digital-labor-into-reliable-tasks" aria-label="Permalink to &quot;Hearth: Turning Digital Labor into Reliable Tasks&quot;">​</a></h1><p class="lead">Hearth is a single-user, self-hosted, long-running, low-interruption, low-token general-purpose personal Agent OS. Its goal is not to create another chat window that needs supervision, but to let repetitive digital labor be confidently delegated, verified, and recovered.</p><h2 id="one-sentence-positioning" tabindex="-1">One-Sentence Positioning <a class="header-anchor" href="#one-sentence-positioning" aria-label="Permalink to &quot;One-Sentence Positioning&quot;">​</a></h2><blockquote><p><strong>Hearth is a general-purpose personal Agent OS with personal context, durable execution, real tools, and multi-device entry points; it frees people from repetitive digital labor rather than creating another chat window that needs supervision.</strong></p></blockquote><p>The product name is Hearth, the repository is <code>hearth-os</code>, the command line is <code>hearth</code>, the long-running service is <code>hearthd</code>, and the package namespace is <code>@hearth/*</code>.</p><h2 id="what-problem-it-solves" tabindex="-1">What Problem It Solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What Problem It Solves&quot;">​</a></h2><p>Existing Agents can often complete a single demo, but are difficult to use over the long term. The problem is usually not model capability, but what lies outside the model:</p><ul><li>Task state is stored in chat history and cannot be reliably recovered after a crash or device switch;</li><li>External side effects lack approval, idempotency, receipts, and reconciliation;</li><li>Permissions, credentials, and memory have no clear boundaries;</li><li>Users must understand the Agent&#39;s internal structure to judge whether it has actually completed;</li><li>Every task repeatedly reads a large amount of context, making token costs uncontrollable;</li><li>The frontend is treated as an afterthought wrapper layer, leaving users with only logs or a CLI.</li></ul><p>Hearth puts these capabilities at the center of the product: <strong>Control Plane, durable execution, parallel Executors, memory, evolution, experience, and evaluation</strong>.</p><h2 id="what-it-is-not" tabindex="-1">What It Is Not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What It Is Not&quot;">​</a></h2><ul><li>Not another Coding Agent;</li><li>Not a Codex wrapper that merely forwards prompts;</li><li>Not black-box automation that hands all permissions to the model;</li><li>Not an enterprise multi-tenant Agent platform;</li><li>Not a tool that requires users to maintain prompts, plugins, and workflows every day.</li></ul><p>In Hearth, Codex is a powerful <strong>parallel Executor</strong>, not the product itself, and not the sole execution brain.</p><h2 id="one-logical-agent-multi-device-execution" tabindex="-1">One Logical Agent, Multi-Device Execution <a class="header-anchor" href="#one-logical-agent-multi-device-execution" aria-label="Permalink to &quot;One Logical Agent, Multi-Device Execution&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>One logical Hearth</span></span>
<span class="line"><span>  ├─ One primary Gateway / Control Plane</span></span>
<span class="line"><span>  ├─ One Event Log / single writer</span></span>
<span class="line"><span>  ├─ agentd on multiple devices</span></span>
<span class="line"><span>  ├─ Phone as the entry point for viewing, approval, takeover, and initiation</span></span>
<span class="line"><span>  └─ Each device registers its own capabilities</span></span></code></pre></div><p>Devices provide only execution capabilities and entry points; they do not replicate identity, sources of truth, or authorization. All facts enter the Event Log; all external side effects pass through the outbox, idempotency keys, and Receipts; all interface states are projections, not sources of truth.</p><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core Capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Problem It Solves</th></tr></thead><tbody><tr><td>Task Control Plane</td><td>Decides what to do, whether it is allowed, when to interrupt, and how to recover</td></tr><tr><td>Durable Execution Kernel</td><td>Turns intent into execution that is recoverable, auditable, and receipt-backed</td></tr><tr><td>Parallel Executors</td><td>Selects Codex, Native, Connector, Browser, GUI, or Human based on capability, risk, and Token cost</td></tr><tr><td>Memory and Evolution</td><td>Enables safe recall of people, projects, preferences, commitments, and experience, and distills repeated successes into controlled skills</td></tr><tr><td>Experience Plane</td><td>Carries interaction through Task cards, approvals, and Artifacts rather than endless chat logs</td></tr><tr><td>Security and Evaluation</td><td>Proves &quot;it can actually do it&quot; through validators, red teaming, fault injection, and stage gates</td></tr></tbody></table><h2 id="current-status" tabindex="-1">Current Status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current Status&quot;">​</a></h2><p>The repository currently contains the complete product, architecture, security, and delivery roadmap. Implementation has not yet begun; Stage 0 and Stage 1 will proceed according to the vertical slice plan in the roadmap.</p><p>Continue reading:</p><ul><li><a href="/hearth-os/en/product/definition.html">Product Definition and Boundaries</a></li><li><a href="/hearth-os/en/architecture/">System Design Overview</a></li><li><a href="/hearth-os/en/delivery/roadmap.html">Phased Product Roadmap</a></li><li><a href="/hearth-os/en/guide/project-status.html">Project Status</a></li></ul>`,22)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
